import os
import json,pandas as pd,numpy as np,hashlib
W=Path(os.environ.get('SCAID_BCELL_OUTPUT', 'work/bcell_state')).resolve();T=W/'tables';r=pd.read_csv(T/'B_state_HC3_models.tsv',sep='\t');cov=pd.read_csv(T/'B_source_label_coverage_by_arm_cohort_batch.tsv',sep='\t');qa=json.loads((W/'provenance/analysis_QA.json').read_text())
family_labels={'original_main_check': 'Original aggregate models (recalculated, unchanged)', 'matched_B_population': 'Aggregate B-cell outcomes in the same 230 individuals', 'state_composition_within_B': 'Source-recorded state fractions among all B cells', 'state_composition_all_PBMC': 'Secondary recorded-state fractions among all source PBMCs', 'state_IFN': 'IFN12 within source-recorded B states', 'common_state_population': 'Shared 205-person population for naive/memory outcomes', 'mixture_adjusted_IFN': 'Aggregate IFN in the same 225 assessed-state individuals', 'cohort4_state_sensitivity': 'Selected processing cohort 4 sensitivity', 'status_consistent_state_sensitivity': 'Consistent source-recorded status sensitivity', 'source_label_coverage': 'Source fine-label coverage diagnostics', 'annotation_coverage_sensitivity': 'At least 90% named-state coverage sensitivity'}
state_labels={'B':'Total B','B_naive':'Naive B','B_mem':'Memory B','B_atypical':'Atypical B','missing_fine_label':'Missing fine label','other_labelled':'Other labelled','total_unresolved':'All unresolved'}
