sections=[]
for family,sub in r.groupby('family',sort=False):
 en=[];raw=[]
 for _,v in sub.iterrows():
  ok=v.status=='estimated';fac=100 if 'fraction' in v.endpoint else 1;digits=2 if fac==100 else 3
  effect=f'{fac*v.adjusted_SLE_minus_HD:.{digits}f} ({fac*v.HC3_CI_low:.{digits}f}, {fac*v.HC3_CI_high:.{digits}f})' if ok else 'Not estimable'
  q=f'{v.BH_q:.3g}' if pd.notna(v.BH_q) else ('Original family unchanged' if family=='original_main_check' else 'Not applicable')
  extra=('Unadjusted' if v.analysis=='assessed_state_population_B_IFN_unadjusted' else ('Adjusted for recorded-state fractions' if v.analysis=='state_fraction_adjusted_B_IFN' else ''))
  note=extra if ok else str(v.reason)
  en.append([state_labels[v.state],endpoint_labels[v.endpoint],f'{int(v.n_SLE)} / {int(v.n_HD)}',effect,q,note])
  raw.append({k:(None if isinstance(x,float) and np.isnan(x) else x.item() if isinstance(x,np.generic) else x) for k,x in v.to_dict().items()})
 # Historical _zh keys contain the same English values for schema compatibility.
 sections.append({'family':family,'title_en':family_labels[family],'title_zh':family_labels[family],'headers_en':headers,'headers_zh':headers,'rows_en':en,'rows_zh':en,'raw_results':raw})
notes_en=['Fraction effects are in percentage points; IFN effects are mean log1p(counts per 10,000) units.','Original aggregate composition uses 162 SLE and 71 references. Aggregate IFN and the same-population B-fraction sensitivity use 159 SLE and 71 references (>=20 B cells).','Named-state composition uses 155 SLE and 70 references: >=20 total B cells and at least one assigned B_naive/B_mem/B_atypical cell. Five B-positive individuals with wholly unassigned fine labels are unavailable for state composition, not subtype-zero observations. All source B cells, including unresolved cells, remain in denominators.','The common 205-person population consists of 136 SLE and 69 references from the original selected batches with >=20 total B cells, >=20 B_naive cells and >=20 B_mem cells; B_atypical is not required. Both state composition and both state IFN outcomes reuse these same individuals and are not independent samples.','State IFN eligibility is >=20 target-state cells in each individual and >=10 eligible individuals in each arm; B_atypical has only three eligible references and remains unavailable.','BH correction is separate by listed planned family. Unavailable planned tests enter adjustment as P=1 but their q is displayed as unavailable. The original aggregate model is only recalculated for equality; its original FDR family is not replaced.','Coverage diagnostics and the >=90% annotation-coverage analysis were added after source-label review and are not external preregistration. Their outcomes do not imply new cell-level QC.','Unresolved labels are retained and described by condition, processing cohort and batch. Sensitivity populations overlap and are not independent replication; within-state IFN differences do not prove intrinsic activation.']
cv=cov[cov.grouping.isin(['condition','cohort_condition'])].copy();coverage_rows=[]
for _,v in cv.iterrows():coverage_rows.append({'condition':v.condition,'cohort':None if pd.isna(v.cohort) else int(v.cohort),'individuals':int(v.n_individuals),'B_cells':int(v.source_B_cells),'missing_label_cells':int(v.missing_fine_label_cells),'other_labelled_cells':int(v.other_labelled_cells),'unresolved_percent_cell_weighted':100*v.cell_weighted_unresolved_fraction,'median_individual_unresolved_percent':100*v.median_individual_unresolved_fraction,'entirely_unassessed_Bpositive_individuals':int(v.n_Bpositive_entirely_unassessed)})
o={'title_en':'Source-recorded B-cell states, IFN12 and matched-population sensitivity','title_zh':'Source-recorded B-cell states, IFN12 and matched-population sensitivity','language':'en','legacy_language_keys_note':'Keys ending in _zh contain English aliases retained for schema compatibility.','main_model_unchanged':True,'models':len(r),'sections':sections,'notes_en':notes_en,'notes_zh':notes_en,'coverage_summary':coverage_rows,'common_population':qa['common_state_eligible'],'common_population_definition':qa['common_population_definition'],'state_composition_population':qa['state_composition_eligible'],'value_table':'tables/B_state_HC3_models.tsv','complete_workbook':'B_Cell_State_Analysis.xlsx'}
(W/'readable_results.json').write_text(json.dumps(o,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
# A short complete narrative for the parent; it refers to source-recorded categories, not newly discovered subtypes.
en=['Results candidate (final)\n','In the same 159 SLE cases and 71 references eligible for aggregate B-cell IFN analysis, the adjusted B-cell fraction differed by 0.03 percentage points (95% CI −2.26 to 2.31), whereas IFN12 differed by 0.171 (95% CI 0.130 to 0.211). The original 233-person composition estimate remains unchanged at −0.24 percentage points.','Source-recorded B states provided a more detailed comparison. Among 155 cases and 70 references with assessed state labels, naive, memory and atypical B-cell fractions differed by 8.49 (95% CI 2.90 to 14.08), −10.14 (−15.56 to −4.73) and 1.79 (0.65 to 2.93) percentage points of all B cells, respectively (BH q≤0.003). Unresolved cells remained in the denominator; five B-positive individuals with no named-state annotations were unavailable for these comparisons.','IFN12 was higher within source-recorded naive B cells (146 cases, 70 references; difference 0.165, 95% CI 0.124 to 0.206) and memory B cells (142 cases, 69 references; 0.166, 0.122 to 0.210). In the shared 136-case/69-reference population eligible for both states, the differences remained positive: 0.151 (0.111 to 0.191) and 0.169 (0.124 to 0.214). Corresponding estimates were also positive in selected processing cohort 4 and in the high-annotation-coverage analysis. These are within-source sensitivity results, not independent replication.','In the same 155-case/70-reference population, the unadjusted-for-state-mixture aggregate IFN contrast was 0.171 (0.130 to 0.212), compared with 0.134 (0.091 to 0.178) after adding the three recorded-state fractions. These estimates allow recorded composition and expression to be examined together without establishing cell-intrinsic activation. Atypical B-cell IFN was not modelled because only three references met the target-cell threshold.','Coverage note: unresolved labels accounted for 8.47% of source B cells in cases and 5.12% in references, with marked processing-cohort differences. The covariate-adjusted unresolved-fraction diagnostic did not identify a clear case–reference difference (−0.13 percentage points; 95% CI −0.95 to 0.68). This does not demonstrate equivalence or random missingness. All missing-label records, including batch-level summaries, are retained.']
(W/'final_results_candidate_en.txt').write_text('\n\n'.join(en)+'\n')
